extends Area2D
## A shell travels on the ground plane and is drawn raised to turret height.
## has_hit is set on the first contact and the shell is freed, so one shell = one hit = one sound.

const DRAW_OFFSET := Vector2(0.0, -10.85)

var shooter = null
var world = null
var dir := Vector2.RIGHT
var speed := 460.0
var damage := 25
var has_hit := false
var _life := 2.0


func _ready() -> void:
	collision_layer = 0
	collision_mask = 1 | 2
	var s := CollisionShape2D.new()
	var c := CircleShape2D.new()
	c.radius = 3.0
	s.shape = c
	add_child(s)
	body_entered.connect(_on_body_entered)


func _physics_process(delta: float) -> void:
	position += dir * speed * delta
	_life -= delta
	if _life <= 0.0:
		queue_free()


func _draw() -> void:
	draw_line(DRAW_OFFSET - dir * 9.0, DRAW_OFFSET, Color(1, 0.8, 0.4, 0.6), 2.0)
	draw_circle(DRAW_OFFSET, 2.5, Color(1, 0.92, 0.6))


func _on_body_entered(body) -> void:
	if has_hit or body == shooter:
		return
	if shooter != null and "team" in body and "team" in shooter and body.team == shooter.team:
		return  # no friendly fire; the shell keeps flying
	has_hit = true
	if body.has_method("take_hit"):
		body.take_hit(self)
	elif body.has_method("take_damage"):
		body.take_damage(damage, shooter)
	if world:
		world.spawn_fx("impact", global_position + DRAW_OFFSET)
	queue_free()

extends "res://scripts/tank.gd"
## Enemy tank: wanders between random waypoints, turns its turret toward YunqiZ and fires when it
## has a clear line of sight. Uses the YunqiZ sprites tinted grey (code, not a separate asset).

var target = null
var arena := Rect2(90, 90, 1100, 540)
var _wp := Vector2.ZERO
var _wp_left := 0.0
var _rng := RandomNumberGenerator.new()


func _ready() -> void:
	super._ready()
	_rng.randomize()
	reload_left = _rng.randf_range(1.5, 3.0)


func _think(delta: float) -> void:
	if target == null or target.is_dead or world == null or world.level_won:
		move_dir = Vector2.ZERO
		return
	_wp_left -= delta
	if _wp_left <= 0.0 or global_position.distance_to(_wp) < 12.0:
		_wp = Vector2(_rng.randf_range(arena.position.x, arena.end.x), _rng.randf_range(arena.position.y, arena.end.y))
		_wp_left = _rng.randf_range(2.0, 4.0)
	var to_wp := _wp - global_position
	move_dir = to_wp.normalized() if to_wp.length() > 12.0 else Vector2.ZERO
	var to_target: Vector2 = target.global_position - global_position
	aim_angle = lerp_angle(aim_angle, to_target.angle(), clampf(delta * 3.0, 0.0, 1.0))
	var off := absf(wrapf(aim_angle - to_target.angle(), -PI, PI))
	if reload_left <= 0.0 and to_target.length() < 700.0 and off < 0.15 and _has_line_of_sight():
		if try_fire():
			reload_left = reload_time + _rng.randf_range(0.0, 1.0)


func _has_line_of_sight() -> bool:
	var q := PhysicsRayQueryParameters2D.create(global_position, target.global_position, 1 | 2, [get_rid()])
	var hit := get_world_2d().direct_space_state.intersect_ray(q)
	return not hit.is_empty() and hit.collider == target


func _play_fire_sound() -> void:
	world.audio.play("fire", -6.0, 0.85, "enemy_fire")


func _play_hit_sound() -> void:
	world.audio.play("player_hit", -8.0, 0.8, "enemy_hit")

extends Node2D
## Test gallery for TEST-REPORT.md: YunqiZ in all 8 facings, its states, the enemy tint and the
## collision circle, drawn in-engine at 2x game size. Open scenes/gallery.tscn and press F6.

const TankScript := preload("res://scripts/tank.gd")  # base tank: no mouse aim, so each turret keeps its own facing
const EnemyScript := preload("res://scripts/enemy.gd")
const NAMES := ["right", "down-right", "down", "down-left\n(mirrored)", "left\n(mirrored)", "up-left\n(mirrored)", "up", "up-right"]
const SIN_E := 0.8192

func _ready() -> void:
	scale = Vector2(2, 2)
	var bg := ColorRect.new()
	bg.color = Color(0.29, 0.24, 0.2)
	bg.position = Vector2(-20, -20)
	bg.size = Vector2(700, 400)
	bg.z_index = -10
	add_child(bg)
	for i in 8:
		var g := i * PI / 4.0
		var t = _tank(TankScript, Vector2(40 + i * 75, 55), Vector2(cos(g), sin(g) * SIN_E).angle())
		t._set_sprite(t.hull, t._hull_tex, i)
		_label(NAMES[i], Vector2(10 + i * 75, 85))
	var states := ["idle", "smoke\n(<=60% health)", "fire\n(<=30% health)", "destroyed", "enemy tint"]
	for i in states.size():
		var pos := Vector2(40 + i * 110, 175)
		var t
		if i == 4:
			t = _tank(EnemyScript, pos, 0.0)
		else:
			t = _tank(TankScript, pos, -0.5)
		if i == 1:
			t.health = 55
			t._update_damage_look()
		elif i == 2:
			t.health = 20
			t._update_damage_look()
		elif i == 3:
			t.die()
		_label(states[i], Vector2(5 + i * 110, 205))
	_label("Green circles = collision shape (radius 16.6 px at game size). Shown at 2x.", Vector2(10, 260))


func _tank(script, pos: Vector2, aim: float):
	var t = script.new()
	t.position = pos
	t.aim_angle = aim
	if script == EnemyScript:
		t.tint = Color(0.58, 0.6, 0.66)
	add_child(t)
	var ring := Line2D.new()
	ring.width = 1.0
	ring.default_color = Color(0.2, 1.0, 0.4, 0.9)
	ring.z_index = 5
	for k in 33:
		ring.add_point(pos + Vector2.RIGHT.rotated(k * TAU / 32.0) * 16.6)
	add_child(ring)
	return t


func _label(text: String, pos: Vector2) -> void:
	var l := Label.new()
	l.text = text
	l.position = pos
	l.scale = Vector2(0.5, 0.5)
	l.add_theme_font_size_override("font_size", 18)
	add_child(l)
